fn v3_fall_back_to_passive(&mut self, version, rnd, player, data, debug):

// --- 게이트 1 (handler.rs:417)
if version < 2 { return }

// --- 게이트 2 (handler.rs:421) : 게임 모드
let game = data.cache.game;                 // OperationData+0x0 -> AbstractGameWithCache+0x0 (dyn fat ptr)
if game.game_mode().tag == 2 /*DeathMatch*/ { return }

// --- 플랜 생성 (handler.rs:424~428)
let plan: BigPlan =
  if game.game_mode().tag == 1 /*SingleLane*/ {
      // handler.rs:425 — 고정 플랜, passive_plan 을 아예 안 부른다
      BigPlan::SinglePlanLine(SinglePlanLine {
          chats: vec![],            // cap=0, ptr=8(dangling), len=0
          in_recall: false,         // +0x18
          line: LineType::Mid,      // +0x19 = 1
      })                            // 판별자 store i64 4
  } else {
      // handler.rs:427 — Moba(tag 0) 경로
      self.passive_plan(version, rnd, player, data, debug)
  };

// --- 룰스코프 검사 (handler.rs:429) : rule_scope::plan_allowed(context, &plan) 가 인라인됨
let ctx = data.context;                     // OperationData+0x8
let t   = ctx.tutorial;                     // GameContext+0x38, TutorialType 0..8
let allowed = match plan.goal() {           // rule_scope.rs:101 -> goal_allowed rule_scope.rs:91
  // BigGoal::Line{line}  -> line_exists(ctx, line) (rule_scope.rs:92) -> TutorialType::spawn_line_minion (runner.rs:275)
  Line{line: Top}    => t in {None0, TopSolo2, Line7, Total8},                    // runner.rs:276/283 spawn_top_minion
  Line{line: Mid}    => t in {None0, MidSolo4, MidBottom5, Line7, Total8},        // runner.rs:277/287 spawn_mid_minion
  Line{line: Bottom} => t in {None0, First1, Bottom3, MidBottom5, Line7, Total8}, // runner.rs:278/291 spawn_bottom_minion
  // BigGoal::Jungle -> rule_scope.rs:95 가 TutorialType::player_count (runner.rs:294) 를 인라인, 조건이 상수접힘
  Jungle{..}         => t in {None0, JungleOnly6, Total8},
  // BigGoal::Epic -> morgard_exists (rule_scope.rs:46) -> spawn_epic (runner.rs:263)
  Epic               => t in {None0, Line7, Total8},
  // BigGoal::Serpen -> serpen_exists (rule_scope.rs:50) -> spawn_serpen (runner.rs:267)
  Serpen             => t in {None0, MidBottom5, Line7, Total8},
  // 나머지는 무조건 허용 (switch 에서 곧장 allowed 블록 %61 로 감)
  Nexus{..} | Battle{..} | Recall => true,
};

if !allowed {
    drop(plan);            // block %70
    return                 // handler.rs:437 — self 는 전혀 안 바뀐다
}

// --- 채택 (handler.rs:432~436)
let tick = game.tick();                          // vtable+0x28
self.mf_swap = (29u8, tick);                     // handler.rs:410 mf_note_swap 인라인, +0x1610/+0x1618
self.v3_lapse_passive_fallbacks += 1;            // handler.rs:433, +0x1628
self.plan = plan;                                // handler.rs:434, +0x5e8 (구 BigPlan drop 후 memcpy 384)
let sp = BigPlan::sub_plan(&mut self.plan, version, rnd, player, data,
                           &self.data /*+0x0,248B*/, &mut self.team_plan /*+0xf8*/,
                           &self.positioning_score /*+0x990,2760B*/, debug); // handler.rs:435
self.sub_plan.merge(&sp);                        // handler.rs:436, +0x768

// 참고: %36/%71/%84/%87 의 invoke 가 언와인딩하면 cleanuppad(%58)에서 임시 BigPlan 을 drop 하고,
//       %82 경로는 self.plan 자리에 백업본(%9)을 되돌려 놓아 이중해제를 막는다(예외안전용, 판정과 무관).
